artifacts.description:
`Accordion.Header` renders an `<h3>` wrapper; the trigger button is a separate child.
    ```tsx
    import { Accordion } from '@tale-ui/react/accordion';

    export function Example() {
      return (
        <Accordion.Root>
          <Accordion.Item id="a">
            <Accordion.Header>
              <Accordion.Trigger>Question</Accordion.Trigger>
            </Accordion.Header>
            <Accordion.Panel>Answer</Accordion.Panel>
          </Accordion.Item>
        </Accordion.Root>
      );
    }
    ```

Do not use `'app-store'`, `'play-store'`, `'ios'`, or `'android'`. The valid values are `'apple'` and `'google'`.
    ```tsx
    import { AppStoreButton } from '@tale-ui/react/app-store-button';

    export function Example() {
      return (
        <>
          <AppStoreButton store="apple" href="https://apps.apple.com/..." />
          <AppStoreButton store="google" href="https://play.google.com/..." />
        </>
      );
    }
    ```

use `Autocomplete.SearchField` with an `aria-label`; Autocomplete renders inline with no popover.
    ```tsx
    import { Autocomplete } from '@tale-ui/react/autocomplete';

    export function Example() {
      return (
        <Autocomplete.Root>
          <Autocomplete.SearchField>
            <Autocomplete.Input placeholder="Search..." />
          </Autocomplete.SearchField>
          <Autocomplete.ListBox>
            <Autocomplete.Item id="apple">Apple</Autocomplete.Item>
            <Autocomplete.Item id="banana">Banana</Autocomplete.Item>
          </Autocomplete.ListBox>
        </Autocomplete.Root>
      );
    }
    ```

when the request is to search/filter items such as fruits, countries, commands, or members, render `Autocomplete.Root` with `useFilter`, `Autocomplete.SearchField`, `Autocomplete.Input`, and `Autocomplete.ListBox` instead of leaving the file empty or substituting `SearchField` or `Combobox`.

    ```tsx
    import { Autocomplete, useFilter } from '@tale-ui/react/autocomplete';

    const fruits = [
      { id: 'apple', label: 'Apple' },
      { id: 'banana', label: 'Banana' },
      { id: 'cherry', label: 'Cherry' },
      { id: 'grape', label: 'Grape' },
      { id: 'mango', label: 'Mango' },
      { id: 'orange', label: 'Orange' },
    ];

    export function FruitAutocomplete() {
      const { contains } = useFilter({ sensitivity: 'base' });
      return (
        <Autocomplete.Root filter={contains}>
          <Autocomplete.SearchField aria-label="Search fruits">
            <Autocomplete.Input placeholder="Search fruits..." />
          </Autocomplete.SearchField>
          <Autocomplete.ListBox aria-label="Fruits">
            {fruits.map((fruit) => (
              <Autocomplete.Item key={fruit.id} id={fruit.id} textValue={fruit.label}>
                {fruit.label}
              </Autocomplete.Item>
            ))}
          </Autocomplete.ListBox>
        </Autocomplete.Root>
      );
    }
    ```

`Avatar.Root` has `overflow: hidden`, so placing `Avatar.Indicator` inside it will clip the indicator badge.
    ```tsx
    import { Avatar } from '@tale-ui/react/avatar';

    export function Example() {
      return (
        <Avatar.Group size="md">
          <Avatar.Root><Avatar.Fallback>AB</Avatar.Fallback></Avatar.Root>
          <Avatar.Root><Avatar.Fallback>CD</Avatar.Fallback></Avatar.Root>
          <Avatar.Count>+3</Avatar.Count>
        </Avatar.Group>
      );
    }
    ```

The Pattern type uses singular nouns. Passing a pluralized value like 'circles' causes Type '"circles"' is not assignable to type 'Pattern'. Use the singular form 'circle' instead.
    ```tsx
    import { BackgroundPattern } from '@tale-ui/react/background-pattern';

    export function DecorativeCircularPattern() {
      return (
        <BackgroundPattern pattern="circle" size="lg" />
      );
    }
    ```

use `variant="error"` instead.

    ```tsx
    import { Badge } from '@tale-ui/react/badge';

    export function Example() {
      return (
        <>
          <Badge variant="success">Active</Badge>
          <Badge variant="error" size="sm">
            Failed
          </Badge>
        </>
      );
    }
    ```

Banner.Root exposes a Banner.Actions sub-part for placing interactive buttons alongside the title and description. Wrap Button components inside Banner.Actions; do not add them as raw children of Banner.Root. Use this for any prompt that asks for a banner with one or more action buttons such as 'Later' (ghost) and 'Update now' (primary).

    ```tsx
    import { Banner } from '@tale-ui/react/banner';
    import { Button } from '@tale-ui/react/button';

    export function UpdateAvailableBanner() {
      return (
        <Banner.Root variant="warning">
          <Banner.Title>Update available</Banner.Title>
          <Banner.Description>A new version is ready to install.</Banner.Description>
          <Banner.Actions>
            <Button variant="ghost">Later</Button>
            <Button variant="primary">Update now</Button>
          </Banner.Actions>
        </Banner.Root>
      );
    }
    ```

`Banner` is a namespace component; calling `<Banner>` directly renders nothing.

    ```tsx
    import { Banner } from '@tale-ui/react/banner';
    import { Icon } from '@tale-ui/react/icon';
    import { InfoIcon } from 'lucide-react';

    export function Example() {
      return (
        <Banner.Root variant="info">
          <Banner.Icon>
            <Icon icon={InfoIcon} size="sm" />
          </Banner.Icon>
          <Banner.Title>Heads up</Banner.Title>
          <Banner.Description>Your trial expires in 3 days.</Banner.Description>
        </Banner.Root>
      );
    }
    ```

`Breadcrumbs.Link` provides separator and `data-current` styling that bare `<Link>` lacks.
    ```tsx
    import { Breadcrumbs } from '@tale-ui/react/breadcrumbs';

    export function Example() {
      return (
        <Breadcrumbs.Root>
          <Breadcrumbs.Item><Breadcrumbs.Link href="#">Home</Breadcrumbs.Link></Breadcrumbs.Item>
          <Breadcrumbs.Item><Breadcrumbs.Link href="#">Products</Breadcrumbs.Link></Breadcrumbs.Item>
          <Breadcrumbs.Item><Breadcrumbs.Link>Current Page</Breadcrumbs.Link></Breadcrumbs.Item>
        </Breadcrumbs.Root>
      );
    }
    ```

The valid variants are `'primary'`, `'neutral'`, `'ghost'`, `'danger'`, `'danger-neutral'`, `'danger-ghost'`, and `'inverse'`. There is no `'link'` variant (use the `Link` component instead) and no `'secondary'` variant; when a prompt asks for a Cancel button or any secondary-action button, use `'neutral'` — never `'secondary'`.
    ```tsx
    import { Button } from '@tale-ui/react/button';

    export function Example() {
      return (
        <>
          <Button variant="primary" size="md">Click me</Button>
          <Button variant="neutral">Neutral</Button>
          <Button variant="ghost">Ghost</Button>
          <Button variant="danger">Danger</Button>
          <Button variant="danger-neutral">Outlined danger</Button>
          <Button variant="danger-ghost">Ghost danger</Button>
          <Button variant="inverse">Inverse</Button>
          <Button variant="primary" isPending>Saving…</Button>
          <Button variant="primary" isPending showTextWhileLoading>Saving…</Button>
        </>
      );
    }
    ```

`Calendar.PreviousButton`, `Calendar.Heading`, and `Calendar.NextButton` must be placed inside `Calendar.Header`; placing them directly in `Calendar.Root` loses the flex layout.

    ```tsx
    import { Calendar } from '@tale-ui/react/calendar';

    export function Example() {
      return (
        <Calendar.Root>
          <Calendar.Header>
            <Calendar.PreviousButton />
            <Calendar.Heading />
            <Calendar.NextButton />
          </Calendar.Header>
          <Calendar.Grid>
            <Calendar.GridHeader>
              {(day) => <Calendar.GridHeaderCell>{day}</Calendar.GridHeaderCell>}
            </Calendar.GridHeader>
            <Calendar.GridBody>{(date) => <Calendar.Cell date={date} />}</Calendar.GridBody>
          </Calendar.Grid>
        </Calendar.Root>
      );
    }
    ```

use `variant="elevated"`; there is also no `variant="raised"`.

    ```tsx
    import { Card } from '@tale-ui/react/card';

    export function Example() {
      return (
        <Card.Root variant="elevated">
          <Card.Header>Title</Card.Header>
          <Card.Body>Content goes here.</Card.Body>
          <Card.Footer>Footer actions</Card.Footer>
        </Card.Root>
      );
    }
    ```

when the request is to display a user's profile photo, name, role/title, skill badges, and action buttons inside a card, render `Card.Root` with `Card.Header`, `Card.Body`, and `Card.Footer`; place `<Image>` in `Card.Header`, wrap body content in `<Column gap="s">` inside `Card.Body`, and wrap footer actions in `<Row gap="s">` inside `Card.Footer`. Use `variant="elevated"` when the prompt requests an elevated card style.

    ```tsx
    import { Card } from '@tale-ui/react/card';
    import { Image } from '@tale-ui/react/image';
    import { Text } from '@tale-ui/react/text';
    import { Column } from '@tale-ui/react/column';
    import { Row } from '@tale-ui/react/row';
    import { Badge } from '@tale-ui/react/badge';
    import { IconButton } from '@tale-ui/react/icon-button';
    import { Icon } from '@tale-ui/react/icon';
    import { Button } from '@tale-ui/react/button';
    import { Pencil } from 'lucide-react';

    export function UserProfileCard() {
      return (
        <Card.Root variant="elevated">
          <Card.Header>
            <Image src="/profile.jpg" alt="Sarah Chen" radius="full" width={80} height={80} />
          </Card.Header>
          <Card.Body>
            <Column gap="s">
              <Text variant="heading">Sarah Chen</Text>
              <Text color="muted">Senior Engineer</Text>
              <Row gap="s">
                <Badge variant="neutral">React</Badge>
                <Badge variant="neutral">TypeScript</Badge>
              </Row>
            </Column>
          </Card.Body>
          <Card.Footer>
            <Row gap="s">
              <IconButton variant="ghost" aria-label="Edit profile">
                <Icon icon={Pencil} />
              </IconButton>
              <Button variant="primary">Message</Button>
            </Row>
          </Card.Footer>
        </Card.Root>
      );
    }
    ```

NOT `PreviousButton` or `NextButton`.
    ```tsx
    import { Carousel } from '@tale-ui/react/carousel';

    export function Example() {
      return (
        <Carousel.Root loop>
          <Carousel.Content>
            <Carousel.Item>Slide 1</Carousel.Item>
            <Carousel.Item>Slide 2</Carousel.Item>
            <Carousel.Item>Slide 3</Carousel.Item>
          </Carousel.Content>
          <Carousel.PreviousTrigger />
          <Carousel.NextTrigger />
        </Carousel.Root>
      );
    }
    ```

calling `<Checkbox>` directly causes "cannot be used as a JSX component" errors.

    ```tsx
    import { Checkbox } from '@tale-ui/react/checkbox';
    import { Icon } from '@tale-ui/react/icon';
    import { Check } from 'lucide-react';

    export function Example() {
      return (
        <Checkbox.Root>
          <Checkbox.Indicator>
            <Icon icon={Check} size="sm" />
          </Checkbox.Indicator>
          Accept terms and conditions
        </Checkbox.Root>
      );
    }
    ```

calling `<CheckboxField>` directly causes "cannot be used as a JSX component" errors.

    ```tsx
    import { CheckboxField } from '@tale-ui/react/checkbox-field';
    import { Icon } from '@tale-ui/react/icon';
    import { Check } from 'lucide-react';

    export function Example() {
      return (
        <CheckboxField.Root>
          <CheckboxField.Button>
            <CheckboxField.Indicator>
              <Icon icon={Check} size="sm" />
            </CheckboxField.Indicator>
            Accept terms and conditions
          </CheckboxField.Button>
        </CheckboxField.Root>
      );
    }
    ```

anti-pattern: `<CheckboxGroup value={new Set(['apple'])} onChange={(v) => setSelected(v)} />`
    ```tsx
    import { CheckboxGroup } from '@tale-ui/react/checkbox-group';
    import { CheckboxField } from '@tale-ui/react/checkbox-field';
    import { Icon } from '@tale-ui/react/icon';
    import { Check } from 'lucide-react';

    export function Example() {
      return (
        <CheckboxGroup label="Favorite fruits">
          <CheckboxField.Root value="apple">
            <CheckboxField.Button>
              <CheckboxField.Indicator><Icon icon={Check} size="sm" /></CheckboxField.Indicator>
              Apple
            </CheckboxField.Button>
          </CheckboxField.Root>
          <CheckboxField.Root value="banana">
            <CheckboxField.Button>
              <CheckboxField.Indicator><Icon icon={Check} size="sm" /></CheckboxField.Indicator>
              Banana
            </CheckboxField.Button>
          </CheckboxField.Root>
        </CheckboxGroup>
      );
    }
    ```

There is no `ColorArea.Gradient` sub-part. The gradient background is rendered automatically by `ColorArea.Root`.
    ```tsx
    import { ColorArea, parseColor } from '@tale-ui/react/color-area';

    export function Example() {
      return (
        <ColorArea.Root defaultValue={parseColor('hsl(0, 100%, 50%)')}>
          <ColorArea.Thumb />
        </ColorArea.Root>
      );
    }
    ```

The hex color text input is `ColorField` from `@tale-ui/react/color-field`. There is no separate `HexColorField` export.
    ```tsx
    import { ColorField } from '@tale-ui/react/color-field';

    export function Example() {
      return (
        <ColorField.Root>
          <ColorField.Label>Color</ColorField.Label>
          <ColorField.Input />
        </ColorField.Root>
      );
    }
    ```

the component reads `localStorage` and `data-color-mode` internally; passing `isSelected`/`onChange` silently does nothing.

    ```tsx
    import { ColorModeToggle } from '@tale-ui/react/color-mode-toggle';
    export function Example() {
      return <ColorModeToggle />;
    }
    ```

There is no `label` prop on `ColorPicker.Root`. It is a headless state provider only.
    ```tsx
    import { ColorPicker } from '@tale-ui/react/color-picker';
    import { ColorArea } from '@tale-ui/react/color-area';
    import { ColorSlider } from '@tale-ui/react/color-slider';

    export function Example() {
      return (
        <ColorPicker.Root defaultValue="hsb(200, 100%, 100%)">
          <ColorArea.Root xChannel="saturation" yChannel="brightness">
            <ColorArea.Thumb />
          </ColorArea.Root>

          <ColorSlider.Root channel="hue">
            <ColorSlider.Track><ColorSlider.Thumb /></ColorSlider.Track>
          </ColorSlider.Root>
        </ColorPicker.Root>
      );
    }
    ```

<!-- multi-idea-ok -->

Use <Column> or a <div> as a shared parent to provide layout. Do not rely on adjacent sibling rendering without a container. When using <Column>, use spacing-token gap values ('s', 'm', 'l'), never component-size values ('sm', 'md', 'lg') — all three component-size names are invalid Gap values and cause TypeScript errors. Map: sm->s, md->m, lg->l. This is the most common error when composing ColorArea with ColorSlider. Even when the prompt says to use a specific gap size, always translate to spacing tokens. CRITICAL: gap="lg" is a frequent error in ColorArea+ColorSlider compositions — it MUST be gap="l".
    ```tsx
    import { ColorArea } from '@tale-ui/react/color-area';
    import { ColorSlider } from '@tale-ui/react/color-slider';
    import { Column } from '@tale-ui/react/column';

    export function HslColorPicker() {
      return (
        <Column gap="l" style={{ width: 240 }}>
          <ColorArea.Root defaultValue="hsl(0, 100%, 50%)" xChannel="saturation" yChannel="lightness">
            <ColorArea.Thumb />
          </ColorArea.Root>

          <ColorSlider.Root channel="hue" defaultValue="hsl(0, 100%, 50%)">
            <ColorSlider.Label>Hue</ColorSlider.Label>
            <ColorSlider.Output />
            <ColorSlider.Track>
              <ColorSlider.Thumb />
            </ColorSlider.Track>
          </ColorSlider.Root>
        </Column>
      );
    }
    ```

pass a CSS color string directly (e.g. `color="#ff0000"`); do not use `parseColor()` or pass a `Color` object, and the prop is `color`, not `value`.

    ```tsx
    import { ColorSwatch } from '@tale-ui/react/color-swatch';
    export function MyComponent() {
      return <ColorSwatch color="#ff0000" />;
    }
    ```

it is not exported from `@tale-ui/react/color-swatch-picker`.
    ```tsx
    import { ColorSwatchPicker } from '@tale-ui/react/color-swatch-picker';
    import { ColorSwatch } from '@tale-ui/react/color-swatch';

    export function Example() {
      return (
        <ColorSwatchPicker.Root>
          <ColorSwatchPicker.Item color="#ff0000"><ColorSwatch /></ColorSwatchPicker.Item>
          <ColorSwatchPicker.Item color="#00ff00"><ColorSwatch /></ColorSwatchPicker.Item>
          <ColorSwatchPicker.Item color="#0000ff"><ColorSwatch /></ColorSwatchPicker.Item>
        </ColorSwatchPicker.Root>
      );
    }
    ```

Omitting `ColorWheel.Track` inside `ColorWheel.Root` will render a blank element with no visible color ring.
    ```tsx
    import { ColorWheel, parseColor } from '@tale-ui/react/color-wheel';

    export function Example() {
      return (
        <ColorWheel.Root defaultValue={parseColor('hsl(0, 100%, 50%)')} outerRadius={100} innerRadius={70}>
          <ColorWheel.Track />
          <ColorWheel.Thumb />
        </ColorWheel.Root>
      );
    }
    ```

React.Key is not the same as the Key type used internally by Combobox.Root. Annotating useState with React.Key | null causes 'Type Key | null is not assignable to type Key | null | undefined' TypeScript errors because the component's selectedKey prop type is incompatible with React.Key. Derive the correct type from the component's own onSelectionChange prop using React.ComponentProps, exactly as you would for TagSelect or GridList controlled selection.
    ```tsx
    import * as React from 'react';
    import { Combobox } from '@tale-ui/react/combobox';

    const countries = [
      { id: 'au', name: 'Australia' },
      { id: 'ca', name: 'Canada' },
      { id: 'gb', name: 'United Kingdom' },
      { id: 'us', name: 'United States' },
    ];

    type SelectedKey = Parameters<NonNullable<React.ComponentProps<typeof Combobox.Root>['onSelectionChange']>>[0];

    export function CountryCombobox() {
      const [selectedKey, setSelectedKey] = React.useState<SelectedKey>(null);

      return (
        <Combobox.Root
          selectedKey={selectedKey}
          onSelectionChange={setSelectedKey}
        >
          <Combobox.Label>Country</Combobox.Label>
          <Combobox.InputGroup>
            <Combobox.Input placeholder="Search countries..." />
            <Combobox.Trigger />
          </Combobox.InputGroup>
          <Combobox.Popover>
            <Combobox.ListBox>
              {countries.map((country) => (
                <Combobox.Item key={country.id} id={country.id} textValue={country.name}>
                  {country.name}
                </Combobox.Item>
              ))}
            </Combobox.ListBox>
          </Combobox.Popover>
        </Combobox.Root>
      );
    }
    ```

open/close is managed internally by right-click interaction.

    ```tsx
    import { ContextMenu } from '@tale-ui/react/context-menu';

    export function Example() {
      return (
        <ContextMenu.Root>
          <ContextMenu.Trigger>Right-click here</ContextMenu.Trigger>
          <ContextMenu.Popup>
            <ContextMenu.MenuList>
              <ContextMenu.Item id="cut">Cut</ContextMenu.Item>
              <ContextMenu.Item id="copy">Copy</ContextMenu.Item>
              <ContextMenu.Separator />
              <ContextMenu.Item id="paste">Paste</ContextMenu.Item>
            </ContextMenu.MenuList>
          </ContextMenu.Popup>
        </ContextMenu.Root>
      );
    }
    ```

When a prompt asks for a credit card (dark, branded, etc.), immediately render CreditCard.Root with the appropriate type prop. Dark brand-coloured cards use type="brand-dark". CreditCard.Root does NOT accept companyName or cardNumber props — passing them causes a TypeScript assignability error because they are not part of RootProps. Use only the documented props: type and width.
    ```tsx
    import { CreditCard } from '@tale-ui/react/credit-card';

    export function DarkBrandCard() {
      return (
        <CreditCard.Root type="brand-dark" />
      );
    }
    ```

There is no `DateField.Input`. The correct sub-part for the segmented input container is `DateField.DateInput`.
    ```tsx
    import { DateField } from '@tale-ui/react/date-field';

    export function Example() {
      return (
        <DateField.Root>
          <DateField.Label>Date</DateField.Label>
          <DateField.DateInput>
            {(segment) => <DateField.Segment segment={segment} />}
          </DateField.DateInput>
        </DateField.Root>
      );
    }
    ```

there is no `Disclosure.Content` sub-part.
    ```tsx
    import { Disclosure } from '@tale-ui/react/disclosure';

    export function Example() {
      return (
        <Disclosure.Root>
          <Disclosure.Trigger>Show more</Disclosure.Trigger>
          <Disclosure.Panel>Hidden content revealed on expand.</Disclosure.Panel>
        </Disclosure.Root>
      );
    }
    ```

valid values are `'neutral'`, `'brand'`, `'error'`, `'warning'`, `'success'`. Raw color names or hex values are not accepted.
    ```tsx
    import { DotIcon } from '@tale-ui/react/dot-icon';

    export function Example() {
      return (
        <>
          <DotIcon color="success" />
          <DotIcon color="error" size="lg" />
        </>
      );
    }
    ```

this is the opposite of `Dialog` and `AlertDialog`.
    ```tsx
    import { Drawer } from '@tale-ui/react/drawer';

    export function Example() {
      return (
        <Drawer.Root>
          <Drawer.Trigger className="tale-button tale-button--neutral">Open Drawer</Drawer.Trigger>
          <Drawer.Backdrop />
          <Drawer.Popup>
            <Drawer.Title>Drawer Title</Drawer.Title>
            <Drawer.Description>Drawer content here.</Drawer.Description>
            <Drawer.Close className="tale-button tale-button--neutral">Cancel</Drawer.Close>
            <Drawer.Close className="tale-button tale-button--primary">Confirm</Drawer.Close>
          </Drawer.Popup>
        </Drawer.Root>
      );
    }
    ```

`DropZone` is a simple component. Pass children (text, icons, buttons) directly inside `<DropZone>`.
    ```tsx
    import { DropZone } from '@tale-ui/react/drop-zone';
    import { FileTrigger } from '@tale-ui/react/file-trigger';
    import { Button } from '@tale-ui/react/button';

    export function Example() {
      return (
        <DropZone onDrop={(e) => console.log('Dropped:', e.items)}>
          <FileTrigger onSelect={(files) => console.log(files)}>
            <Button>Drop files here or click to browse</Button>
          </FileTrigger>
        </DropZone>
      );
    }
    ```

the available sub-parts are `Root`, `Icon`, `Title`, `Description`, and `Actions` only.
    ```tsx
    import { EmptyState } from '@tale-ui/react/empty-state';
    import { Icon } from '@tale-ui/react/icon';
    import { Button } from '@tale-ui/react/button';
    import { InboxIcon } from 'lucide-react';

    export function Example() {
      return (
        <EmptyState.Root>
          <EmptyState.Icon><Icon icon={InboxIcon} size="lg" /></EmptyState.Icon>
          <EmptyState.Title>No messages</EmptyState.Title>
          <EmptyState.Description>Your inbox is empty.</EmptyState.Description>
          <EmptyState.Actions><Button variant="primary">Compose</Button></EmptyState.Actions>
        </EmptyState.Root>
      );
    }
    ```

When the request is to show a heading and optional description for a state where there is no content (e.g. 'No results', 'Nothing here yet', 'Your inbox is empty'), render EmptyState.Root with EmptyState.Title and EmptyState.Description instead of leaving the file empty, returning null, or substituting Column + Text. The available sub-parts are Root, Icon, Title, Description, and Actions — do not invent sub-parts like EmptyState.Header or EmptyState.Content.
    ```tsx
    import { EmptyState } from '@tale-ui/react/empty-state';

    export function NoResults() {
      return (
        <EmptyState.Root>
          <EmptyState.Title>No results</EmptyState.Title>
          <EmptyState.Description>Try using different search terms to find what you're looking for.</EmptyState.Description>
        </EmptyState.Root>
      );
    }
    ```

pass an `<Icon>` component as children; import both `FeaturedIcon` from `@tale-ui/react/featured-icon` and the lucide icon from `lucide-react`.

    ```tsx
    import { FeaturedIcon } from '@tale-ui/react/featured-icon';
    import { Icon } from '@tale-ui/react/icon';
    import { Bell } from 'lucide-react';
    export function MyComponent() {
      return <FeaturedIcon size="lg"><Icon icon={Bell} /></FeaturedIcon>;
    }
    ```

`Field.Root` is a plain layout container. It does not accept `isInvalid`, `isRequired`, `isDisabled`, or `isReadOnly`. For validated fields, use a component like `Input.Root` that has React Aria field context built in.

    ```tsx
    import { Field } from '@tale-ui/react/field';

    export function Example() {
      return (
        <>
          <Field.Root>
            <Field.Label>Email</Field.Label>
            <Field.Control>
              <input className="tale-input" placeholder="you@example.com" />
            </Field.Control>
            <Field.Description>We'll never share your email.</Field.Description>
            // For validation errors: // <Field.Error>Please enter a valid email.</Field.Error>
          </Field.Root>
          // Field.Item wraps multiple controls in a row:
          <Field.Root>
            <Field.Label>Phone</Field.Label>
            <Field.Item>
              <select className="tale-select__trigger">...</select>
              <input className="tale-input" placeholder="555-0000" />
