consumers do not depend on `react-aria-components` directly, so that import causes "Cannot find module" errors. Derive the selection type from `GridList.Root` props with `React.ComponentProps`, or omit the callback parameter annotation.

    ```tsx
    import * as React from 'react';
    import { useState } from 'react';
    import { GridList } from '@tale-ui/react/grid-list';

    type SelectionValue = Parameters<
      NonNullable<React.ComponentProps<typeof GridList.Root>['onSelectionChange']>
    >[0];

    export function Example() {
      const [selectedKeys, setSelectedKeys] = useState<SelectionValue>(new Set());

      return (
        <GridList.Root
          aria-label="Items"
          selectionMode="multiple"
          selectedKeys={selectedKeys}
          onSelectionChange={setSelectedKeys}
        >
          <GridList.Item id="1" textValue="Item 1">
            Item 1
          </GridList.Item>
          <GridList.Item id="2" textValue="Item 2">
            Item 2
          </GridList.Item>
        </GridList.Root>
