when the request is specifically to crop an image — including any mention of '1:1 aspect ratio', 'square crop', or 'avatar photo' — immediately output the full ImageCropper.Root composition without deliberation. Never return empty code, time out, or substitute Image. Import centerCrop, makeAspectCrop, and the Crop type all from @tale-ui/react/image-cropper. Initialize crop state as useState<Crop>() (no initial value), wire an onLoad handler on ImageCropper.Img to compute the initial centered crop, and pass aspect={1} to ImageCropper.Root for square crops.
    ```tsx
    import * as React from 'react';
    import { ImageCropper, centerCrop, makeAspectCrop } from '@tale-ui/react/image-cropper';
    import type { Crop } from '@tale-ui/react/image-cropper';

    export function AvatarCropper() {
      const [crop, setCrop] = React.useState<Crop>();

      function handleImageLoad(event: React.SyntheticEvent<HTMLImageElement>) {
        const { width, height } = event.currentTarget;
        setCrop(
          centerCrop(
            makeAspectCrop({ unit: '%', width: 80 }, 1, width, height),
            width,
            height
          )
        );
      }

      return (
        <ImageCropper.Root crop={crop} onChange={setCrop} aspect={1}>
          <ImageCropper.Img
            src="/avatar.jpg"
            alt="User avatar to crop"
            onLoad={handleImageLoad}
            style={{ maxHeight: 320, width: '100%' }}
          />
        </ImageCropper.Root>
      );
    }
    ```

When a prompt asks for a labeled text input field (optionally with a description or error message), render Input.Root with Input.Label, Input.Input, and optionally Input.Description instead of leaving the file empty, returning null, or substituting TextField or a bare <input> element.

