When MultiSelect.Root includes a MultiSelect.Footer, do NOT use the items prop with a render-function child — TypeScript types children as ReactNode and rejects a function. Instead, map the items array explicitly with .map() so all children are ReactNode. Derive the selection type from onSelectionChange via React.ComponentProps — never import Selection from react-aria-components. Compute selected count from state handling both Set and the 'all' sentinel.

    ```tsx
    import * as React from 'react';
    import { MultiSelect } from '@tale-ui/react/multi-select';
    import { Button } from '@tale-ui/react/button';

    const frameworks = [
      { id: 'react', name: 'React' },
      { id: 'vue', name: 'Vue' },
      { id: 'angular', name: 'Angular' },
      { id: 'svelte', name: 'Svelte' },
      { id: 'solid', name: 'SolidJS' },
    ];

    type SelectionValue = Parameters<
      NonNullable<React.ComponentProps<typeof MultiSelect.Root>['onSelectionChange']>
    >[0];

    export function FrameworkMultiSelect() {
      const [selected, setSelected] = React.useState<SelectionValue>(new Set());

      const selectedCount = selected === 'all' ? frameworks.length : (selected as Set<string>).size;

      return (
        <MultiSelect.Root
          label="JavaScript frameworks"
          placeholder={selectedCount > 0 ? `${selectedCount} selected` : 'Select frameworks…'}
          description="Choose the frameworks for your project."
          selectedKeys={selected}
          onSelectionChange={setSelected}
        >
          {frameworks.map((framework) => (
            <MultiSelect.Item key={framework.id} id={framework.id} textValue={framework.name}>
              {framework.name}
            </MultiSelect.Item>
          ))}
          <MultiSelect.Footer>
            <Button variant="ghost" onPress={() => setSelected(new Set())}>
              Reset
            </Button>
            <Button
              variant="ghost"
              onPress={() => setSelected(new Set(frameworks.map((f) => f.id)))}
            >
              Select All
            </Button>
          </MultiSelect.Footer>
        </MultiSelect.Root>
      );
    }
    ```

