      return (
        <Radio.Group label="Favorite color">
          <Radio.Root value="red">
            <Radio.Indicator /> Red
          </Radio.Root>
          <Radio.Root value="green">
            <Radio.Indicator /> Green
          </Radio.Root>
          <Radio.Root value="blue">
            <Radio.Indicator /> Blue
          </Radio.Root>
        </Radio.Group>
      );
    }
