            </RangeCalendar.GridHeader>
            <RangeCalendar.GridBody>
              {(date) => <RangeCalendar.Cell date={date} />}
            </RangeCalendar.GridBody>
          </RangeCalendar.Grid>
        </RangeCalendar.Root>
      );
    }
    ```

`RatingBadge` does not accept children text; pass the numeric score via the `value` prop.
